param([string]$DatabaseUrl=$env:OPPORTUNITY_TEST_DATABASE_URL)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($DatabaseUrl)){throw 'Explicit disposable loopback database URL required'};$uri=[Uri]$DatabaseUrl;if($uri.Host-notin@('127.0.0.1','localhost','::1')-or$DatabaseUrl-match'(?i)supabase'){throw 'Refusing unsafe database'}
$psql='C:\Program Files\PostgreSQL\15\bin\psql.exe';if(-not(Test-Path $psql)){$psql=(Get-Command psql).Source};$root=(Resolve-Path(Join-Path $PSScriptRoot '..\..')).Path
function Run([string]$file){&$psql -X -v ON_ERROR_STOP=1 -q -d $DatabaseUrl -f $file;if($LASTEXITCODE-ne 0){throw "psql failed: $file"}}
&$psql -X -v ON_ERROR_STOP=1 -q -d $DatabaseUrl -c "create schema if not exists extensions;create extension if not exists pgcrypto schema extensions;do `$`$begin if not exists(select 1 from pg_roles where rolname='anon')then create role anon;end if;if not exists(select 1 from pg_roles where rolname='authenticated')then create role authenticated;end if;if not exists(select 1 from pg_roles where rolname='service_role')then create role service_role;end if;end`$`$;alter role service_role bypassrls;create table public.deals(id uuid primary key default gen_random_uuid());"
Run(Join-Path $root 'supabase/migrations/20260821000100_create_acquisition_opportunities.sql');Run(Join-Path $root 'supabase/migrations/20260822000100_create_opportunity_ingestion_foundation.sql');Run(Join-Path $root 'supabase/migrations/20260825000100_create_property_intelligence_identity_source_foundation.sql');Run(Join-Path $root 'supabase/migrations/20260826000100_create_property_intelligence_observations.sql');Run(Join-Path $PSScriptRoot 'property-intelligence-opportunity-subject-authority-rollback.integration.sql');Write-Host 'Property Intelligence Opportunity-subject authority rollback passed.'
